"""chem_rk7_mkfrel (RK7 holder 2): builds tools/chem_rk7_frel.py from WR7's tools/chem_wr7_froundl.py (read-only:
R50's fround = the rounding + FreezePlacer, with WR7's guard and R8's lever) by anchored replacements, each found
exactly once:
  * option --relp @rel/<file>: with --fp, the rows are placed by tools/chem_rk7_relplace.RelPlacer (every relation of
    a relation file, any bit, F tables) instead of R50's FreezePlacer (bit-0 wires only);
  * the stage's residues are applied with their own modulus (2 or 4) inside the signed range [-32, 31];
  * the end checks my relations (chem_rk7_rel.check) on the placed rows.
    python chem_rk7_mkfrel.py            (writes tools/chem_rk7_frel.py, then: python tools/chem_rk7_frel.py --help)
"""
import os

T = os.path.dirname(os.path.abspath(__file__))
src = open(os.path.join(T, "chem_wr7_froundl.py"), encoding="utf-8").read()


def rep(s, old, new):
    n = s.count(old)
    assert n == 1, (n, old[:80])
    return s.replace(old, new)


s = src
s = rep(s, '    ap.add_argument("--fp", action="store_true",',
        '    ap.add_argument("--relp", default="", help="chem_rk7: with --fp, place rows by chem_rk7_relplace.RelPlacer '
        'on this relation file (@file)")\n    ap.add_argument("--fp", action="store_true",')
s = rep(s, '        FP = FreezePlacer(R, B, FCH, WIRES, n_one=N, ncols=N - 1)\n',
        '        if a.relp:      # chem_rk7: every relation of a relation file, placed exactly (RelPlacer)\n'
        '            from chem_rk7_relplace import RelPlacer\n'
        '            from chem_rk7_rel import parse as _rparse, check as _rcheck\n'
        '            RELS = _rparse(a.relp)\n'
        '            assert not WIRES and not FCH, "--relp replaces --wires / --fp-code"\n'
        '            FP = RelPlacer(R, B, RELS, n_one=N, ncols=N - 1)\n'
        '            log(f"relp: {len(RELS)} relations a row on {len(FP.pl.cc)} columns (moduli {sorted(set(FP.mod[FP.pl.cc].tolist()))}), batches {FP.lo}-{FP.hi}")\n'
        '        else:\n'
        '            FP = FreezePlacer(R, B, FCH, WIRES, n_one=N, ncols=N - 1)\n')
s = rep(s, '                fps = fpm[fpj] == 2\n                fpi, fpj = fpi[fps], fpj[fps]\n'
           '                fpz = fpr[fpi, fpj] + 2 * np.round((fpt[fpi, fpj] - fpr[fpi, fpj]) / 2)\n'
           '                fpz = np.where(fpz > HALF - 1, fpz - 2, np.where(fpz < -HALF, fpz + 2, fpz))\n',
        '                fps = fpm[fpj] >= 2          # chem_rk7: modulus 2 (bit 0) or 4 (bits 0, 1)\n'
        '                fpi, fpj = fpi[fps], fpj[fps]\n'
        '                fpmm = fpm[fpj]\n'
        '                fpz = fpr[fpi, fpj] + fpmm * np.round((fpt[fpi, fpj] - fpr[fpi, fpj]) / fpmm)\n'
        '                fpz = np.where(fpz > 31, fpz - fpmm, np.where(fpz < -32, fpz + fpmm, fpz))    # chem_rk7: [-32, 31]\n')
s = rep(s, '            fpbad = _fpviol(wv, FCH, np.asarray(addr) // 16, np.asarray(addr) % 16, WIRES, np.asarray(addr))\n',
        '            if a.relp:      # chem_rk7: my relations on the placed rows\n'
        '                fpbad = int(_rcheck(np.mod(wv, 128), np.asarray(addr), RELS))\n'
        '            else:\n'
        '                fpbad = _fpviol(wv, FCH, np.asarray(addr) // 16, np.asarray(addr) % 16, WIRES, np.asarray(addr))\n')
s = s.replace('"""', '"""chem_rk7_frel (RK7 holder 2): GENERATED by tools/chem_rk7_mkfrel.py from tools/chem_wr7_froundl.py; with\n'
              '--fp --relp @rel/<file> the rows are placed by tools/chem_rk7_relplace.RelPlacer (every relation, exactly).\n\n', 1)
s = rep(s, '        from r50_chem_lbl_hook import FreezePlacer\n        from r50_chem_lbl_place import violations as _fpviol\n',
        '        if not a.relp:  # chem_rk7: the Placer modules only for R50\'s own wires (they import R51\'s tool)\n'
        '            from r50_chem_lbl_hook import FreezePlacer\n'
        '            from r50_chem_lbl_place import violations as _fpviol\n')
out = os.path.join(T, "chem_rk7_frel.py")
open(out, "w", encoding="utf-8").write(s)
print("wrote", out, len(s))
